export const COUNT=12,OFFSETS=[-.8,.4,0,.8,-.4,.2,-.6,.6,-.2,1,-1,.3];
export function create(){return{seeds:[0,1],benefit:2,coordination:8,switching:1.5,bridge:false,compatibility:0,hold:true};}
export function validate(s){if(!s||!Array.isArray(s.seeds)||new Set(s.seeds).size!==s.seeds.length||s.seeds.some(x=>!Number.isInteger(x)||x<0||x>=COUNT)||typeof s.bridge!=='boolean'||typeof s.hold!=='boolean'||!Number.isFinite(s.benefit)||s.benefit<0||s.benefit>12||!Number.isFinite(s.coordination)||s.coordination<0||s.coordination>12||!Number.isFinite(s.switching)||s.switching<0||s.switching>6||!Number.isFinite(s.compatibility)||s.compatibility<0||s.compatibility>1)throw Error('Invalid adoption assumptions');return s;}
export function edges(s){const out=[];for(let i=0;i<12;i++)for(let j=i+1;j<12;j++)if(Math.floor(i/6)===Math.floor(j/6))out.push([i,j]);if(s.bridge)out.push([2,6],[5,9]);return out;}
export function initial(s){validate(s);return Array.from({length:12},(_,i)=>s.seeds.includes(i));}
export function assess(s,adopted){const links=edges(s);return adopted.map((current,i)=>{const neighbours=links.flatMap(([a,b])=>a===i?[b]:b===i?[a]:[]),share=neighbours.filter(j=>adopted[j]).length/neighbours.length,personal=s.benefit+OFFSETS[i],newValue=personal+s.coordination*(share+s.compatibility*(1-share)),oldValue=s.coordination*(1-share),gain=newValue-oldValue,held=s.hold&&s.seeds.includes(i),next=held?true:current?(gain < -s.switching?false:true):gain>s.switching;return{current,next,share,personal,newValue,oldValue,gain,held};});}
export function simulate(s,limit=24){validate(s);const history=[initial(s)],seen=new Set([history[0].join(',')]);let status='limit reached';for(let t=1;t<=limit;t++){const next=assess(s,history.at(-1)).map(x=>x.next);history.push(next);if(next.every((x,i)=>x===history.at(-2)[i])){status='stable';break;}const key=next.join(',');if(seen.has(key)){status='cycle';break;}seen.add(key);}return{history,status,final:history.at(-1),rounds:history.length-1};}
